#define PI 3.141592653

vec2 Rotation(vec2 uv,float angle)
{
    mat2 rotationMatrix = mat2(cos(angle), -sin(angle),
                            sin(angle),  cos(angle));
    return rotationMatrix*uv;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    uv-=0.5;
    uv.x*=iResolution.x/iResolution.y;
    uv*=2.5;


    float angle=(atan(-uv.x,-uv.y)+PI)/PI/2.0;
    float index=floor(angle*3.0);
    vec2 TriangleUV=Rotation(uv,radians(-120.0*index));

    float x1=TriangleUV.x;
    float y1=TriangleUV.y;
    float m=-sqrt(3.0);
    float b=1.0;
    float y2=abs(m*x1-y1+b)/sqrt(m*m+1.0);
    y2*=sign(y1-(m*x1+b));

    vec2 ToTop=vec2(x1,y1)-vec2(0,b);
    float x2d=length(ToTop);
    float dsign=sign(dot(ToTop,vec2(-b/m,-b)));
    float x2=sqrt(x2d*x2d-y2*y2)*dsign;
    x2/=sqrt(3.0)*b;
    x2=x2*2.0-1.0;
    y2/=sqrt(3.0)*b/2.0;

    float x=x2;
    float y=y2;

    int num=int(floor(mod(iTime,5.0)));
    for(int i=1;i<=num;i++)
    {
        vec2 xy=vec2(x,y);
        xy.x=abs(xy.x);
        xy.x+=1.0/3.0*sign(-xy.x);

        xy=Rotation(xy,radians(-30.0));
        float k=sqrt(3.0)/3.0;
        float d=abs(k*abs(xy.x)-xy.y)/sqrt(1.0+k*k);

        float NewY=d*sign(xy.y-k*abs(xy.x))*3.0;
        float l=length(xy);
        float NewX=sqrt(l*l-d*d)*3.0/2.0;

        x=NewX*2.0-1.0;
        y=NewY;
    }

    float col=smoothstep(0.075*(float(num)+1.0),0.05*(float(num)+1.0),abs(y));

    vec3 result=vec3(x,y,col);//x,y,col

    fragColor = vec4(result,1.0);
}
